do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero,markets,exchange,country) values ($q$SCT$q$,$q$Softcat$q$,null,null,true,false,array[$q$LSE$q$]::text[],null,$q$GB$q$) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero, markets=case when cardinality(excluded.markets)>0 then excluded.markets else public.companies.markets end, exchange=coalesce(excluded.exchange, public.companies.exchange), country=coalesce(excluded.country, public.companies.country);
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$11:11 Systems$q$,$q$private_company$q$),($q$Blaby District Council$q$,$q$institution$q$),($q$Capital Group$q$,$q$private_company$q$),($q$Commvault$q$,$q$public_company$q$),($q$Exertis$q$,$q$private_company$q$),($q$Lenovo$q$,$q$public_company$q$),($q$Mawer Investment Management$q$,$q$private_company$q$),($q$Microsoft$q$,$q$public_company$q$),($q$Nutanix$q$,$q$public_company$q$),($q$Oakland Group Services Limited$q$,$q$private_company$q$),($q$Park Place Technologies$q$,$q$private_company$q$),($q$Perspicuity$q$,$q$private_company$q$),($q$Samsung$q$,$q$public_company$q$),($q$Steel and Alloy$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$During the year, the Group completed the acquisition of Oakland Group Services Limited and its subsidiary.$q$),(2,$q$Earlier in the year Softcat completed the acquisition of Oakland and management presented proposals to the Committee in respect of the associated accounting treatment.$q$),(3,$q$Fifteen colleagues from our Armed Forces network, South Coast and Bristol offices, walked 110km around the Isle of Wight with support from Lenovo and Commvault, while another group of eight completed a$q$),(4,$q$Following further review, the Board agreed that the opportunity to acquire Oakland would be beneficial for the identified stakeholders and it approved the acquisition.$q$),(5,$q$Following review, the Committee confirmed that no adjustment was required to take account of the acquisition of Oakland Group Services Ltd during the year, as the FY2025 impact on underlying operating profit was not considered material for the purpose of determining the bonus outcome.$q$),(6,$q$In April 2025, Softcat acquired Oakland Group Services Limited, a specialist provider of data and AI consultancy services, significantly enhancing our capability in an exciting growth segment.$q$),(7,$q$In June, we hosted a customer summit, a unique Cyber-security was the most common technology priority among respondents 47% event delivered in partnership with Microsoft, to help business leaders understand the art of the possible and where to focus their efforts.$q$),(8,$q$Mawer Investment Management Limited 9,946,370 4.9% 9,943,553 4.9% Capital Group 9,938,753 4.9% 9,938,753 4.9%$q$),(9,$q$On 4 April 2025, the Group acquired 100% of the share capital of Oakland Group Services Limited, a non-listed company based in the United Kingdom and specialising in the provision of data platform, data strategy, data governance, data analytics and artificial intelligence consultancy.$q$),(10,$q$S&A began working with Softcat back in 2023.$q$),(11,$q$Softcat arranged opportunities for BDC to try out various devices and ultimately decided on Samsung Galaxy Book 4 laptops.$q$),(12,$q$The Ethnic and Cultural Diversity network celebrated Lunar New Year with an origami workshop and traditional Chinese food, in collaboration with our partners VIQU Recruitment, 11:11 Systems and Perspicuity.$q$),(13,$q$The Nutanix solution provides S&A with an infrastructure capable of securely and effectively meeting its demands now and into the future.$q$),(14,$q$To celebrate LGBTQ+ History Month, Softcat partnered with Exertis and BCS to host an event focused on advancing LGBTQ+ inclusion in technology.$q$),(15,$q$We determined that centralised audit procedures can be performed on the entire consolidated financial statements, with the exception of Oakland Group Services Limited which was acquired during the period and was not identified as an individually relevant component.$q$),(16,$q$We have recently launched our first certified carbon neutral service for global third-party maintenance and monitoring, in collaboration with Softcat partner Park Place Technologies.$q$),(17,$q$Workplace GP growth was more modest reflecting the impact of Microsoft incentive changes and ongoing subdued demand for devices.$q$),(18,$q$considering and agreeing the acquisition of Oakland to accelerate our strategic objectives$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$acquires$q$,$q$SCT$q$,$q$Oakland Group Services Limited$q$,$q${6,4,18,2,5,1,15,9}$q$::int[],$q${p26,p33,p74,p86,p106,p149,p138,p166}$q$::text[],100,$q$exact$q$,$q$ownership$q$,null),(2,$q$partners$q$,$q$SCT$q$,$q$Microsoft$q$,$q${7}$q$::int[],$q${p9}$q$::text[],null,null,null,null),(3,$q$partners$q$,$q$SCT$q$,$q$Park Place Technologies$q$,$q${16}$q$::int[],$q${p11}$q$::text[],null,null,null,null),(4,$q$sells_to$q$,$q$SCT$q$,$q$Blaby District Council$q$,$q${11}$q$::int[],$q${p20}$q$::text[],null,null,null,null),(5,$q$sells_to$q$,$q$SCT$q$,$q$Steel and Alloy$q$,$q${10}$q$::int[],$q${p21}$q$::text[],null,null,null,null),(6,$q$supplies$q$,$q$Nutanix$q$,$q$SCT$q$,$q${13}$q$::int[],$q${p21}$q$::text[],null,null,null,null),(7,$q$supplies$q$,$q$Microsoft$q$,$q$SCT$q$,$q${17}$q$::int[],$q${p24}$q$::text[],null,null,null,null),(8,$q$supplies$q$,$q$Samsung$q$,$q$SCT$q$,$q${11}$q$::int[],$q${p20}$q$::text[],null,null,null,null),(9,$q$partners$q$,$q$SCT$q$,$q$Exertis$q$,$q${14}$q$::int[],$q${p36}$q$::text[],null,null,null,null),(10,$q$partners$q$,$q$SCT$q$,$q$11:11 Systems$q$,$q${12}$q$::int[],$q${p36}$q$::text[],null,null,null,null),(11,$q$partners$q$,$q$SCT$q$,$q$Perspicuity$q$,$q${12}$q$::int[],$q${p36}$q$::text[],null,null,null,null),(12,$q$partners$q$,$q$SCT$q$,$q$Lenovo$q$,$q${3}$q$::int[],$q${p36}$q$::text[],null,null,null,null),(13,$q$partners$q$,$q$SCT$q$,$q$Commvault$q$,$q${3}$q$::int[],$q${p36}$q$::text[],null,null,null,null),(14,$q$invests$q$,$q$Mawer Investment Management$q$,$q$SCT$q$,$q${8}$q$::int[],$q${p133}$q$::text[],4.9,$q$exact$q$,$q$ownership$q$,null),(15,$q$invests$q$,$q$Capital Group$q$,$q$SCT$q$,$q${8}$q$::int[],$q${p133}$q$::text[],4.9,$q$exact$q$,$q$ownership$q$,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$SCT$q$ then ticker=$q$SCT$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,cost_usd,status,review_status) values ('filings_extraction','batch',$q$SCT Softcat annual report 2025 (year to 31 Jul 2025) (M14)$q$,'claude-sonnet-5-5 via Claude Code session',1.0387,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; isnew := false; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,trust_status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else $q$2025-07-31$q$::date end,$q$annual_report$q$,$q$staged$q$,null,run_id,$q$2025-07-31$q$::date,r.note) returning id into rid; isnew := true; end if; if isnew then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,null,r.sec[k],t,true,null from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
